import React, { useEffect, useRef, useState } from 'react';
import { View, Text, Pressable, ScrollView, TextInput, StyleSheet, useWindowDimensions, Platform, Linking } from 'react-native';
import Ionicons from '@expo/vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import type { Session } from '@supabase/supabase-js';
import { addDays, balanceFor, canEdit, Challenge, checkinFor, completion, dateRange, finesFor, Goal, goalsOn, money, scheduleGoals, todayIn, validateGoal, weeklyProgress, weekStart } from './src/domain';
import { seed, starterGoals } from './src/seed';
import { supabase } from './src/supabase';
import * as repo from './src/repository';
import ChallengeDetails from './src/ChallengeDetails';
import ChallengeConfiguration from './src/ChallengeConfiguration';
import Home from './src/Home';
import Celebration, { CelebrationEvent } from './src/Celebration';
import DayMood from './src/DayMood';
import { dayMood as getDayMood } from './src/day-mood';

const C = { bg: '#F7F8F4', white: '#FFFFFF', inset: '#EEF1E9', line: '#E3E7DE', ink: '#202C25', muted: '#647064', green: '#276248', pale: '#E7EFE4', orange: '#A14F30', peach: '#FBEEE5' };
type IconName = React.ComponentProps<typeof Ionicons>['name'];
type Page = 'Today' | 'Challenges' | 'Progress' | 'Ledger' | 'Account' | 'Create' | 'Detail' | 'Configuration';
const tabs: { name: Page; icon: IconName }[] = [{ name: 'Today', icon: 'grid-outline' }, { name: 'Challenges', icon: 'flag-outline' }, { name: 'Progress', icon: 'stats-chart-outline' }, { name: 'Ledger', icon: 'wallet-outline' }];
const formatDate = (date: string, short = false) => new Date(date + 'T12:00:00Z').toLocaleDateString('en-IN', { day: 'numeric', month: short ? 'short' : 'long', timeZone: 'UTC' });
const uid = () => `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
function Icon({ name, size = 20, color = C.muted }: { name: string; size?: number; color?: string }) { return <Ionicons name={name as IconName} size={size} color={color} />; }
function Button({ children, onPress, icon, secondary = false, disabled = false, small = false, label }: { children: React.ReactNode; onPress: () => void; icon?: string; secondary?: boolean; disabled?: boolean; small?: boolean; label?: string }) {
  return <Pressable accessibilityRole="button" accessibilityLabel={label ?? (typeof children === 'string' ? children : undefined)} accessibilityState={{ disabled }} disabled={disabled} onPress={onPress} style={({ pressed, hovered }: any) => [s.button, secondary && s.buttonSecondary, small && s.buttonSmall, disabled && { opacity: .45 }, (pressed || hovered) && !disabled && { opacity: .8 }]}>{icon && <Icon name={icon} size={17} color={secondary ? C.green : C.white} />}<Text style={[s.buttonText, secondary && { color: C.green }]}>{children}</Text></Pressable>;
}
function Field({ label, value, onChange, placeholder, numeric, multiline = false, secure = false }: { label: string; value: string; onChange: (v: string) => void; placeholder?: string; numeric?: boolean; multiline?: boolean; secure?: boolean }) {
  return <View style={s.field}><Text style={s.label}>{label}</Text><TextInput accessibilityLabel={label} value={value} onChangeText={onChange} placeholder={placeholder} placeholderTextColor={C.muted} secureTextEntry={secure} multiline={multiline} keyboardType={numeric ? 'number-pad' : 'default'} autoCapitalize="none" style={[s.input, multiline && { minHeight: 86, textAlignVertical: 'top' }]} /></View>;
}
function Badge({ children, warn = false }: { children: React.ReactNode; warn?: boolean }) { return <View style={[s.badge, warn && { backgroundColor: C.peach }]}><Text style={[s.badgeText, warn && { color: C.orange }]}>{children}</Text></View>; }
function Avatar({ name, small = false, second = false }: { name: string; small?: boolean; second?: boolean }) { return <View style={[s.avatar, small && { width: 32, height: 32 }, second && { backgroundColor: '#F0E5D8' }]}><Text style={[s.avatarText, small && { fontSize: 12 }]}>{name.split(' ').map(n => n[0]).slice(0, 2).join('').toUpperCase()}</Text></View>; }
function Heading({ children, aside }: { children: React.ReactNode; aside?: React.ReactNode }) { return <View style={s.sectionHeading}><Text style={s.h2}>{children}</Text>{aside}</View>; }

export default function App() {
  const { width } = useWindowDimensions(); const mobile = width < 760; const narrow = width < 1140;
  const scrollRef = useRef<React.ComponentRef<typeof ScrollView>>(null);
  const [showHome, setShowHome] = useState(() => Platform.OS !== 'web' || !['#workspace', '#account'].includes(window.location.hash));
  const [page, setPage] = useState<Page>(() => Platform.OS === 'web' && window.location.hash === '#account' ? 'Account' : 'Today'); const [challenges, setChallenges] = useState<Challenge[]>([]);
  const [selected, setSelected] = useState(''); const [demo, setDemo] = useState(true); const [demoUser, setDemoUser] = useState('demo-you');
  const [session, setSession] = useState<Session | null>(null); const [ready, setReady] = useState(false); const [busy, setBusy] = useState(false); const [recovery, setRecovery] = useState(false);
  const [error, setError] = useState(''); const [message, setMessage] = useState(''); const [date, setDate] = useState(todayIn());
  const [draft, setDraft] = useState<Record<string, boolean>>({}); const [note, setNote] = useState(''); const [dirty, setDirty] = useState(false);
  const [joinCode, setJoinCode] = useState(''); const [payAmount, setPayAmount] = useState(''); const [payNote, setPayNote] = useState('');
  const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [displayName, setDisplayName] = useState(''); const [signup, setSignup] = useState(false);
  const [configurationDirty, setConfigurationDirty] = useState(false);
  const [celebration, setCelebration] = useState<CelebrationEvent | null>(null);
  const celebrationId = useRef(0);
  const activePage = page === 'Detail' || page === 'Configuration' ? 'Challenges' : page;
  const userId = demo ? demoUser : session?.user.id ?? '';
  const challenge = challenges.find(c => c.id === selected) ?? challenges[0];
  const today = todayIn(challenge?.timezone); const member = challenge?.members.find(m => m.id === userId);
  const selectedGoals = challenge ? goalsOn(challenge, date) : [];
  const todayGoals = challenge ? goalsOn(challenge, today) : [];
  const myName = member?.name ?? (demo ? 'Helen' : session?.user.user_metadata?.display_name ?? 'Friend');
  const balance = challenge ? balanceFor(challenge, userId, today) : { due: 0, paid: 0, total: 0, credit: 0 };

  useEffect(() => { let active = true;
    (async () => { try { const saved = await AsyncStorage.getItem('befit-demo-v1'); if (!active) return; const items = saved ? JSON.parse(saved) as Challenge[] : seed(); setChallenges(items); setSelected(items[0]?.id ?? ''); } catch { if (active) { setChallenges(seed()); setError('Local demo data could not be loaded. A fresh preview is shown.'); } } finally { if (active) setReady(true); } })();
    if (Platform.OS === 'web') { const style = document.createElement('style'); style.id = 'be-fit-web'; style.textContent = 'body{margin:0;background:#F7F8F4} *{box-sizing:border-box} :focus-visible{outline:3px solid #276248!important;outline-offset:3px} ::selection{background:#D7E8CB;color:#202C25} input,textarea{caret-color:#276248} a{color:#276248} [role=button]{touch-action:manipulation}'; document.head.appendChild(style); document.title = 'Be Fit — Better together'; }
    return () => { active = false; if (Platform.OS === 'web') document.getElementById('be-fit-web')?.remove(); };
  }, []);
  useEffect(() => { if (!supabase) return; const { data } = supabase.auth.onAuthStateChange((event, next) => { setSession(next); if (event === 'PASSWORD_RECOVERY') { setShowHome(false); setRecovery(true); setPage('Account'); } }); return () => data.subscription.unsubscribe(); }, []);
  useEffect(() => { if (ready && demo) AsyncStorage.setItem('befit-demo-v1', JSON.stringify(challenges)).catch(() => setError('Your browser could not save the demo. Keep this tab open or enable local storage.')); }, [challenges, demo, ready]);
  useEffect(() => {
    if (!challenge) { setDraft({}); setNote(''); setDirty(false); return; }
    const values: Record<string, boolean> = {}; for (const g of goalsOn(challenge, date)) { const entry = checkinFor(challenge, g.id, userId, date); if (entry) values[g.id] = entry.done; }
    setDraft(values); setNote(challenge.checkins.find(x => x.userId === userId && x.date === date)?.note ?? ''); setDirty(false);
  }, [challenge?.id, challenge?.checkins, userId, date]);
  useEffect(() => { const timer = setInterval(() => { const next = todayIn(challenge?.timezone); if (next !== today && !dirty) setDate(next); }, 30000); return () => clearInterval(timer); }, [today, challenge?.timezone, dirty]);
  useEffect(() => { if (!message) return; const timer = setTimeout(() => setMessage(''), 6000); return () => clearTimeout(timer); }, [message]);
  useEffect(() => { if (demo || !session || dirty || configurationDirty || busy) return; const timer = setInterval(() => { refresh().catch(e => setError(`Could not refresh group progress: ${e.message}`)); }, 30000); return () => clearInterval(timer); }, [demo, session, dirty, configurationDirty, busy, selected]);

  useEffect(() => { scrollRef.current?.scrollTo({ y: 0, animated: false }); }, [page, selected]);

  async function act(fn: () => Promise<void>) { setError(''); setBusy(true); try { await fn(); } catch (e) { setError(e instanceof Error ? e.message : 'Something went wrong. Please try again.'); } finally { setBusy(false); } }
  async function refresh(selectId?: string) { const items = await repo.loadChallenges(); setChallenges(items); if (selectId) setSelected(selectId); else if (!items.some(c => c.id === selected)) setSelected(items[0]?.id ?? ''); }
  function choose(c: Challenge) { if (dirty || configurationDirty) { setError('Save or discard your changes before switching challenges.'); return; } setSelected(c.id); setDate(todayIn(c.timezone)); setPage('Detail'); }
  function go(next: Page) { if (configurationDirty || dirty && (next === 'Detail' || next === 'Configuration')) { setError('Save or discard your changes before leaving this screen.'); return; } setError(''); setPage(next); }
  function openHome() {
    if (dirty || configurationDirty) { setError('Save or discard your changes before leaving this screen.'); return; }
    setCelebration(null); setShowHome(true);
    if (Platform.OS === 'web') window.history.replaceState(null, '', '#home');
  }
  function enterWorkspace(account = false, createAccount = false) {
    setSignup(createAccount); setError(''); setPage(account ? 'Account' : 'Today'); setShowHome(false);
    if (Platform.OS === 'web') window.history.replaceState(null, '', account ? '#account' : '#workspace');
  }
  function updateChallenge(next: Challenge) { setChallenges(items => items.map(c => c.id === next.id ? next : c)); }
  function celebrate(kind: CelebrationEvent['kind'], message: string) { setCelebration({ id: ++celebrationId.current, kind, message }); }
  function markDraft(goalId: string, done: boolean) {
    if (draft[goalId] === done) return;
    setDraft(prev => ({ ...prev, [goalId]: done })); setDirty(true);
    if (done) celebrate('goal', 'Nice! Goal marked done. Save your check-in.');
  }
  async function saveHistoryGoal(day: string, goalId: string, done: boolean) {
    if (!challenge || busy) return;
    if (checkinFor(challenge, goalId, userId, day)?.done === done) return;
    await act(async () => {
      if (!canEdit(challenge, day, todayIn(challenge.timezone), userId) || !goalsOn(challenge, day).some(g => g.id === goalId)) throw new Error('This goal cannot be edited on this date.');
      const existingNote = challenge.checkins.find(x => x.userId === userId && x.date === day)?.note ?? '';
      const entry = { userId, goalId, date: day, done, note: existingNote };
      if (demo) updateChallenge({ ...challenge, checkins: [...challenge.checkins.filter(x => !(x.userId === userId && x.date === day && x.goalId === goalId)), entry] });
      else { await repo.saveCheckins(challenge.id, [entry], existingNote); await refresh(); }
      if (done) celebrate('goal', 'Goal complete. Nice work!');
    });
  }
  async function saveConfiguration(input: { name: string; description: string; goals?: Goal[] }): Promise<boolean> {
    if (!challenge) return false; let saved = false;
    await act(async () => {
      if (challenge.ownerId !== userId) throw new Error('Only the challenge creator can change configuration.');
      if (demo) updateChallenge({ ...challenge, name: input.name, description: input.description, goals: input.goals ? scheduleGoals(challenge, input.goals, todayIn(challenge.timezone), uid) : challenge.goals });
      else { await repo.configureChallenge(challenge.id, input); await refresh(); }
      setConfigurationDirty(false); saved = true;
    });
    return saved;
  }
  function changeDate(next: string) { if (dirty) { setError('Save or discard your changes before choosing another day.'); return; } setDate(next); setError(''); }
  async function saveDay() { if (!challenge || !canEdit(challenge, date, today, userId)) return; await act(async () => {
    const entries = Object.entries(draft).map(([goalId, done]) => ({ goalId, done, date, userId, note: note.trim() }));
    if (!entries.length) throw new Error('Mark at least one goal Done or Missed before saving.');
    if (demo) updateChallenge({ ...challenge, checkins: [...challenge.checkins.filter(x => !(x.userId === userId && x.date === date && draft[x.goalId] !== undefined)), ...entries] });
    else { await repo.saveCheckins(challenge.id, entries, note.trim()); await refresh(); }
    setDirty(false); setMessage('Check-in saved. A little better, together.');
    celebrate('checkin', selectedGoals.every(g => draft[g.id] === true) ? 'All goals complete. What a day!' : 'Check-in saved. Thanks for showing up.');
  }); }
  async function pay() { if (!challenge) return; await act(async () => { const amount = Number(payAmount); if (!Number.isInteger(amount) || amount < 1 || amount > balance.due) throw new Error(`Enter a whole-rupee amount between ₹1 and ${money(balance.due)}.`);
    const payment = { id: uid(), userId, amount, date: today, note: payNote.trim() || 'Manually recorded payment' };
    if (demo) updateChallenge({ ...challenge, payments: [...challenge.payments, payment] }); else { await repo.recordPayment(challenge.id, payment); await refresh(); }
    setPayAmount(''); setPayNote(''); setMessage('Payment recorded. This is a manual record, not a money transfer.');
  }); }
  async function authenticate() { await act(async () => { if (dirty) throw new Error('Save or discard your demo check-in before switching workspaces.'); if (!supabase) throw new Error('Add your Supabase URL and publishable key to .env, run the migration, then restart Expo.');
    if (!email.includes('@') || password.length < 8) throw new Error('Enter a valid email and a password of at least 8 characters.');
    if (signup && !displayName.trim()) throw new Error('Add your name so friends know it is you.');
    const result = signup ? await supabase.auth.signUp({ email: email.trim(), password, options: { data: { display_name: displayName.trim() } } }) : await supabase.auth.signInWithPassword({ email: email.trim(), password });
    if (result.error) throw result.error;
    if (!result.data.session) { setMessage('Check your email to confirm your account, then sign in here.'); return; }
    const items = await repo.loadChallenges(); setSession(result.data.session); setDemo(false); setChallenges(items); setSelected(items[0]?.id ?? ''); setPassword(''); setDirty(false); setPage(items.length ? 'Today' : 'Challenges');
  }); }

  const nav = <>{tabs.map(tab => <Pressable key={tab.name} accessibilityRole="tab" accessibilityLabel={tab.name} accessibilityState={{ selected: activePage === tab.name }} onPress={() => go(tab.name)} style={({ hovered }: any) => [s.navItem, mobile && s.mobileNavItem, activePage === tab.name && s.navActive, hovered && { backgroundColor: C.pale }]}><Icon name={tab.icon} color={activePage === tab.name ? C.green : C.muted} size={mobile ? 21 : 19} /><Text style={[s.navText, mobile && { fontSize: 11 }, activePage === tab.name && { color: C.green, fontWeight: '700' }]}>{tab.name}</Text>{!mobile && tab.name === 'Challenges' && <Text style={s.navCount}>{challenges.length}</Text>}</Pressable>)}</>;
  const doneCount = selectedGoals.filter(g => draft[g.id] === true).length ?? 0;
  const marked = Object.keys(draft).length;
  const previewFine = selectedGoals.filter(g => g.frequency === 'daily' && (draft[g.id] === false || date < today && draft[g.id] === undefined)).reduce((sum, g) => sum + g.penalty, 0) ?? 0;
  const editable = challenge ? canEdit(challenge, date, today, userId) : false;

  if (showHome) return <Home onStart={() => enterWorkspace(true, true)} onSignIn={() => enterWorkspace(true)} onExplore={() => enterWorkspace()} shared={!demo} />;

  return <View style={s.app}>
    <Celebration event={celebration} />
    {!mobile && <View style={s.sidebar}><Pressable accessibilityRole="button" accessibilityLabel="Be Fit home" onPress={openHome} style={[s.brand, { minHeight: 44 }]}><View style={s.brandMark}><Icon name="leaf-outline" color={C.white} size={24} /></View><Text style={s.brandText}>be fit<Text style={{ color: C.green }}>.</Text></Text></Pressable><View style={s.nav}>{nav}</View><View style={s.sidebarBottom}><View style={s.smallNote}><Icon name="people-outline" size={22} color={C.green} /><Text style={s.noteTitle}>Good habits. Great company.</Text><Text style={s.noteCopy}>Showing up is easier when someone’s in it with you.</Text></View><Pressable accessibilityRole="button" onPress={() => go('Account')} style={s.profile}><Avatar name={myName} small /><View style={{ flex: 1 }}><Text style={s.profileName}>{myName}</Text><Text style={s.caption}>{demo ? 'Local demo' : 'Your account'}</Text></View><Icon name="settings-outline" size={18} /></Pressable></View></View>}
    <View style={s.workspace}>
      <View style={[s.topbar, mobile && { paddingHorizontal: 20, minHeight: 64 }]}>{mobile ? <Pressable accessibilityRole="button" accessibilityLabel="Be Fit home" onPress={openHome} style={{ minHeight: 44, justifyContent: 'center' }}><Text style={[s.brandText, { fontSize: 24 }]}>be fit.</Text></Pressable> : <View style={s.row}><Icon name="people-outline" size={18} /><Text style={s.topLabel}>Your accountability space</Text></View>}<View style={s.row}><Badge>{demo ? 'Demo workspace' : 'Shared workspace'}</Badge><Pressable accessibilityRole="button" accessibilityLabel="Open account settings" onPress={() => go('Account')}><Avatar name={myName} small /></Pressable></View></View>
      <ScrollView key={`${page}:${selected}`} ref={scrollRef} style={{ flex: 1 }} contentContainerStyle={[s.scroll, mobile && { padding: 20, paddingTop: 12, paddingBottom: 110 }]}>
        <View style={s.content}>
          {demo && <View style={[s.demoNotice, mobile && { marginBottom: 12, paddingBottom: 4, minHeight: 44 }]}><View style={[s.row, { flex: 1 }]}><Icon name="flask-outline" size={16} color={C.green} /><Text style={s.demoCopy}>{mobile ? 'Sample data · saved on this device.' : 'Try it out. This is sample data, saved only on this device.'}</Text></View><Pressable accessibilityRole="button" onPress={() => go('Account')} style={s.textAction}><Text style={s.link}>Connect account</Text><Icon name="arrow-forward" size={15} color={C.green} /></Pressable></View>}
          {!!error && <View accessibilityRole="alert" style={s.error}><Icon name="alert-circle-outline" color={C.orange} /><Text style={[s.body, { color: C.orange, flex: 1 }]}>{error}</Text><Pressable accessibilityRole="button" accessibilityLabel="Dismiss error" onPress={() => setError('')} style={s.iconButton}><Icon name="close" color={C.orange} /></Pressable></View>}
          {!!message && <View accessibilityLiveRegion="polite" style={s.success}><Icon name="checkmark-circle-outline" color={C.green} /><Text style={[s.body, { flex: 1, color: C.green }]}>{message}</Text></View>}
          {recovery && session && <View style={[s.panel, { maxWidth: 600 }]}><View style={s.panelPad}><Heading>Choose a new password</Heading><Field label="New password" value={password} onChange={setPassword} secure placeholder="At least 8 characters" /><Button disabled={busy} onPress={() => act(async () => { if (password.length < 8) throw new Error('Use a password of at least 8 characters.'); const result = await supabase!.auth.updateUser({ password }); if (result.error) throw result.error; setRecovery(false); setPassword(''); setMessage('Password updated. You can now open your shared workspace.'); })}>Update password</Button></View></View>}
          {!demo && <View style={[s.row, { justifyContent: 'flex-end', marginBottom: 16 }]}><Button secondary small icon="refresh-outline" disabled={busy || dirty || configurationDirty} onPress={() => act(async () => { await refresh(); setMessage('Group progress refreshed.'); })}>Refresh group</Button></View>}
          {!ready ? <View style={s.empty}><Text style={s.h2}>Getting your training log ready…</Text></View> : <>
          {page === 'Today' && challenge && <>
            <View style={[s.pageHeading, mobile && { marginBottom: 14 }]}><View style={{ flex: 1 }}><Text style={[s.h1, mobile && { fontSize: 24, lineHeight: 31 }]}>{mobile ? `Let’s show up, ${myName.split(' ')[0]}.` : 'Small steps. Shared wins.'}</Text>{!mobile && <Text style={s.subtitle}>Hey {myName.split(' ')[0]}, let’s make today count.</Text>}</View>{!mobile && <Button secondary icon="add" onPress={() => go('Create')}>New challenge</Button>}</View>
            <Pressable accessibilityRole="button" accessibilityLabel="View challenge overview" onPress={() => go('Detail')} style={[s.challengeHeader, mobile && { padding: 12, marginBottom: 14 }]}><View style={[s.row, { flexWrap: 'wrap' }]}><View style={s.challengeEmblem}><Icon name="flag-outline" color={C.green} size={22} /></View><View style={{ flex: 1 }}><Text style={s.challengeTitle}>{challenge.name}</Text><Text style={s.caption}>{mobile ? `${challenge.members.length} friends · ${formatDate(challenge.end, true)} finish` : `${formatDate(challenge.start, true)} – ${formatDate(challenge.end, true)} · ${challenge.members.length} friends`}</Text></View><Badge>{today < challenge.start ? 'Upcoming' : today > challenge.end ? 'Completed' : 'In it together'}</Badge></View><View style={[s.challengeFooter, mobile && { display: 'none' }]}><Text style={s.caption}>{challenge.description}</Text><Text style={s.caption}>Day {Math.max(0, Math.min(dateRange(challenge.start, challenge.end).length, dateRange(challenge.start, today).length))} of {dateRange(challenge.start, challenge.end).length}</Text></View></Pressable>
            <View style={[s.mainColumns, narrow && s.column]}>
              <View style={{ flex: 1, minWidth: 0 }}>
                <View style={s.panel}><View style={[s.panelPad, mobile && { padding: 16 }]}><WeekPicker userId={userId} challenge={challenge} date={date} today={today} dirty={dirty} onChange={changeDate} /><View style={s.checkinSubhead}><Text style={s.label}>{date === today ? 'Today’s goals' : formatDate(date)}</Text><Text style={s.caption}>{doneCount} of {selectedGoals.length} done</Text></View><View style={s.progressTrack}><View style={[s.progressFill, { width: `${selectedGoals.length ? doneCount / selectedGoals.length * 100 : 0}%` }]} /></View><DayMood challenge={challenge} userId={userId} date={date} today={today} draft={draft} compact /></View>
                  {!editable && <View style={s.lockNote}><Icon name="lock-closed-outline" size={15} /><Text style={s.caption}>Read only · You can edit today and yesterday within your membership dates.</Text></View>}
                  {selectedGoals.map((g, index) => { const state = draft[g.id]; const weekly = g.frequency === 'weekly' ? weeklyProgress(challenge, g, userId, date) : null; return <View key={g.id} style={[s.goalRow, mobile && { paddingHorizontal: 16 }, index > 0 && { borderTopWidth: 1, borderTopColor: C.line }]}><View style={[s.goalIcon, state === true && { backgroundColor: C.pale }]}><Icon name={g.icon} color={state === true ? C.green : C.muted} size={22} /></View><View style={{ flex: 1, minWidth: 0, paddingRight: mobile ? 0 : 220 }}><Text style={s.goalTitle}>{g.title}</Text><Text style={s.goalDescription}>{g.description}</Text><View style={[s.row, { gap: 6, marginTop: 7, flexWrap: 'wrap' }]}><Text style={[s.ruleText, !g.penalty && { color: C.green }]}>{g.penalty ? `${money(g.penalty)} / ${g.frequency === 'weekly' ? 'week missed' : 'miss'}` : 'No penalty'}</Text>{weekly && <Text style={s.ruleText}> · {weekly.done}/{weekly.target} this week</Text>}</View><View style={[s.row, { gap: 6, marginTop: 12 }, !mobile && { position: 'absolute', right: 0, top: 0, marginTop: 0 }]}>{[true, false].map(value => <Pressable key={String(value)} accessibilityRole="button" accessibilityLabel={`${value ? 'Done' : 'Missed'}: ${g.title}`} {...(Platform.OS === 'web' ? { 'aria-pressed': state === value } : {})} accessibilityState={{ selected: state === value, disabled: !editable || busy }} disabled={!editable || busy} onPress={() => markDraft(g.id, value)} style={({ hovered }: any) => [s.checkButton, state === value && (value ? s.checkedDone : s.checkedMissed), hovered && editable && { borderColor: C.green }]}><Icon name={value ? 'checkmark' : 'close'} size={16} color={state === value ? value ? C.green : C.orange : C.muted} /><Text style={[s.checkText, state === value && { color: value ? C.green : C.orange, fontWeight: '700' }]}>{value ? 'Done' : 'Missed'}</Text></Pressable>)}{state === undefined && <Text style={[s.caption, { marginLeft: 4 }]}>Pending</Text>}</View></View></View>; })}
                  <View style={[s.panelPad, { borderTopWidth: 1, borderTopColor: C.line }]}><Field label="A note for the day (optional)" value={note} onChange={v => { if (editable) { setNote(v.slice(0, 500)); setDirty(true); } }} placeholder="A small win, a tough day, anything to share…" /><View style={[s.saveRow, mobile && s.column]}><View><Text style={s.fineLabel}>Daily fine preview <Text style={s.fineAmount}>{money(previewFine)}</Text></Text><Text style={s.caption}>{date === today ? 'Pending goals aren’t overdue until midnight.' : 'Unmarked daily goals count as missed.'}</Text></View><Button icon="checkmark" disabled={!editable || busy || !dirty || !marked} onPress={saveDay}>{busy ? 'Saving…' : 'Save check-in'}</Button></View>{dirty && <Pressable accessibilityRole="button" onPress={() => { const restored: Record<string, boolean> = {}; selectedGoals.forEach(g => { const e = checkinFor(challenge, g.id, userId, date); if (e) restored[g.id] = e.done; }); setDraft(restored); setNote(challenge.checkins.find(x => x.userId === userId && x.date === date)?.note ?? ''); setDirty(false); }} style={s.textAction}><Text style={s.link}>Discard unsaved changes</Text></Pressable>}</View>
                </View>
              </View>
              <View style={[s.aside, narrow && { width: '100%' }]}>
                <View style={s.groupPanel}><Heading aside={<Icon name="people-outline" size={19} />}>In your corner</Heading><Text style={s.caption}>Today’s check-ins. Everyone shows up differently.</Text>{challenge.members.map((m, i) => { const checked = challenge.checkins.filter(x => x.userId === m.id && x.date === today && todayGoals.some(g => g.id === x.goalId)); const done = checked.filter(x => x.done).length; return <View key={m.id} style={s.friendRow}><Avatar name={m.name} second={i % 2 === 1} /><View style={{ flex: 1 }}><Text style={s.friendName}>{m.name}{m.id === userId ? ' (you)' : ''}</Text><Text style={s.caption}>{checked.length ? `${done} of ${todayGoals.length} goals done` : 'Yet to check in'}</Text></View><Text accessibilityLabel={`${m.name}: ${getDayMood(challenge, m.id, today, today).label}`} style={{ fontSize: 23 }}>{getDayMood(challenge, m.id, today, today).emoji}</Text></View>; })}<Button secondary small icon="person-add-outline" onPress={() => go('Challenges')}>Invite a friend</Button></View>
                <View style={s.duesPanel}><View style={s.row}><Icon name="wallet-outline" color={C.orange} size={19} /><Text style={s.duesHeading}>Your outstanding dues</Text></View><Text style={s.duesAmount}>{money(balance.due)}</Text><Text style={s.duesCopy}>{balance.due ? 'A fresh check-in. A fresh chance to turn things around.' : 'All settled. Keep the good days coming.'}</Text><Pressable accessibilityRole="button" onPress={() => go('Ledger')} style={s.duesLink}><Text style={[s.link, { color: C.orange }]}>View your ledger</Text><Icon name="arrow-forward" size={16} color={C.orange} /></Pressable></View>
                <View style={s.weeklyNote}><Icon name="calendar-outline" color={C.green} size={20} /><Text style={s.noteTitle}>Consistency beats perfection.</Text><Text style={s.noteCopy}>Weekly goals give you room for rest. Miss a day? You can still meet your target.</Text><Pressable accessibilityRole="button" onPress={() => go('Progress')} style={s.textAction}><Text style={s.link}>See the bigger picture</Text><Icon name="arrow-forward" size={15} color={C.green} /></Pressable></View>
              </View>
            </View>
          </>}
          {page === 'Today' && !challenge && <Empty title="Your next chapter starts here." body="Create a challenge, choose a few goals, and bring a friend along." action="Create a challenge" onPress={() => go('Create')} />}
          {page === 'Challenges' && <><View style={[s.pageHeading, mobile && s.column]}><View><Text style={s.h1}>Better with your people.</Text><Text style={s.subtitle}>Shared goals. A little friendly accountability.</Text></View><Button icon="add" onPress={() => go('Create')}>New challenge</Button></View><View style={[s.joinPanel, mobile && s.column]}><View style={{ flex: 1 }}><Text style={s.h2}>Got an invite?</Text><Text style={s.caption}>Ask a friend for their challenge code.</Text></View><View style={[s.row, { flexWrap: 'wrap' }]}><TextInput accessibilityLabel="Invite code" value={joinCode} onChangeText={setJoinCode} placeholder="Enter code" placeholderTextColor={C.muted} autoCapitalize="characters" style={[s.input, { width: mobile ? 150 : 190 }]} /><Button secondary disabled={busy || !joinCode.trim()} onPress={() => act(async () => { if (demo) throw new Error('Invite codes connect real accounts. Connect Supabase and sign in to join a friend’s challenge.'); const id = await repo.joinChallenge(joinCode); await refresh(id); setJoinCode(''); setPage('Today'); setDate(todayIn()); })}>Join challenge</Button></View></View>{!challenges.length && <Text style={s.body}>No challenges yet. Create one or join a friend’s.</Text>}{challenges.map(c => <View key={c.id} style={[s.challengeCard, mobile && { padding: 20 }]}><View style={[s.row, { flexWrap: 'wrap' }]}><View style={s.challengeEmblem}><Icon name="flag-outline" size={25} color={C.green} /></View><View style={{ flex: 1 }}><Text style={s.challengeTitle}>{c.name}</Text><Text style={s.caption}>{formatDate(c.start, true)} – {formatDate(c.end, true)} · {goalsOn(c, [c.start, todayIn(c.timezone), c.end].sort()[1]!).length} goals · {c.members.length} friends</Text></View><Button secondary small onPress={() => choose(c)}>Open challenge</Button></View><Text style={[s.body, { marginTop: 18, marginBottom: 20 }]}>{c.description}</Text><View style={[s.inviteRow, mobile && s.column]}><View><Text style={s.label}>Invite code: {c.invite}</Text><Text style={s.caption}>{demo ? 'Example code · demo invites do not connect devices' : 'Share privately. Anyone with this code can join.'}</Text></View><Button secondary small icon="copy-outline" onPress={() => act(async () => { if (Platform.OS === 'web' && navigator.clipboard) { await navigator.clipboard.writeText(c.invite); setMessage('Invite code copied. Share it with your friend.'); } else setMessage(`Invite code: ${c.invite}`); })}>Copy code</Button></View></View>)}</>}
          {page === 'Detail' && challenge && <ChallengeDetails key={`${challenge.id}:${userId}`} challenge={challenge} userId={userId} today={today} mobile={mobile} busy={busy} onConfigure={() => go('Configuration')} onBack={() => go('Challenges')} onLedger={() => go('Ledger')} onMark={saveHistoryGoal} />}
          {page === 'Configuration' && challenge && <ChallengeConfiguration key={`${challenge.id}:${userId}`} challenge={challenge} demo={demo} userId={userId} today={today} mobile={mobile} busy={busy} onBack={() => go('Detail')} onSave={saveConfiguration} onDirtyChange={setConfigurationDirty} />}
          {page === 'Create' && <CreateForm mobile={mobile} busy={busy} onCancel={() => go('Challenges')} onSubmit={input => act(async () => { if (dirty) throw new Error('Save or discard your current check-in first.'); let id: string; if (demo) { id = uid(); const c: Challenge = { ...input, id, invite: uid().replace('-', '').slice(-8).toUpperCase(), ownerId: userId, goals: input.goals.map(g => ({ ...g, id: uid() })), members: [{ id: userId, name: myName, joined: input.start }], checkins: [], payments: [] }; setChallenges(prev => [...prev, c]); } else { id = await repo.createChallenge(input); await refresh(id); } setSelected(id); setDate(input.start); setPage('Today'); setMessage(demo ? 'Challenge created in your local demo.' : 'Challenge created. Your invite code is ready.'); })} />}
          {page === 'Progress' && challenge && <><View style={s.pageHeading}><View><Text style={s.h1}>Every day adds up.</Text><Text style={s.subtitle}>Your shared progress in {challenge.name}.</Text></View></View><View style={s.panel}><View style={s.panelPad}><Heading aside={<Badge>Sunday – Saturday</Badge>}>This week, together</Heading><Text style={s.caption}>Daily goal completion through yesterday. Weekly sessions are tracked separately.</Text></View>{challenge.members.map((m, i) => { const progress = completion(challenge, m.id, weekStart(today), addDays(today, -1)); return <View key={m.id} style={s.progressMember}><View style={s.row}><Avatar name={m.name} second={i % 2 === 1} /><View style={{ flex: 1 }}><Text style={s.friendName}>{m.name}{m.id === userId ? ' (you)' : ''}</Text><Text style={s.caption}>{progress.done} / {progress.total} daily goals completed</Text></View><Text style={s.percent}>{progress.percent}%</Text></View><View style={[s.progressTrack, { marginTop: 18 }]}><View style={[s.progressFill, { width: `${progress.percent}%` }]} /></View>{todayGoals.filter(g => g.frequency === 'weekly').map(g => { const p = weeklyProgress(challenge, g, m.id, today); return <View key={g.id} style={[s.row, { marginTop: 18 }]}><Icon name={g.icon} size={18} color={C.green} /><Text style={[s.body, { flex: 1 }]}>{g.title}</Text><Badge>{p.done} / {p.target} sessions</Badge></View>; })}</View>; })}</View><View style={s.panel}><View style={s.panelPad}><Heading>The last seven days</Heading><Text style={s.caption}>Each mark is one day’s daily goals, excluding weekly targets.</Text></View>{challenge.members.map(m => <View key={m.id} style={s.progressMember}><Text style={s.friendName}>{m.name}</Text><View style={[s.row, { marginTop: 18, gap: mobile ? 6 : 14 }]}>{dateRange(addDays(today, -6), today).map(d => { const p = completion(challenge, m.id, d, d); const future = d >= today; return <View key={d} style={{ flex: 1, alignItems: 'center', gap: 8 }}><Text style={s.caption}>{new Date(d + 'T12:00:00Z').toLocaleDateString('en', { weekday: 'narrow', timeZone: 'UTC' })}</Text><View style={[s.historyDay, { backgroundColor: future || !p.total ? C.inset : p.percent === 100 ? C.green : C.peach }]}><Text style={{ color: future || !p.total ? C.muted : p.percent === 100 ? C.white : C.orange, fontSize: 12, fontWeight: '600' }}>{future ? 'Now' : !p.total ? '—' : `${p.percent}%`}</Text></View></View>; })}</View></View>)}</View></>}
          {page === 'Ledger' && challenge && <><View style={s.pageHeading}><View><Text style={s.h1}>A fair account.</Text><Text style={s.subtitle}>Every fine explained. Every payment recorded.</Text></View></View><View style={[s.ledgerSummary, mobile && { gap: 16 }]}>{[{ label: 'Your outstanding', value: balance.due, color: C.orange }, { label: 'Total fines', value: balance.total, color: C.ink }, { label: 'Recorded payments', value: balance.paid, color: C.green }].map(item => <View key={item.label} style={{ flex: 1 }}><Text style={s.caption}>{item.label}</Text><Text style={[s.ledgerValue, mobile && { fontSize: 25 }, { color: item.color }]}>{money(item.value)}</Text></View>)}</View>{balance.credit > 0 && <View style={s.success}><Text style={s.body}>You have {money(balance.credit)} credit after a corrected check-in. It will offset future fines.</Text></View>}<View style={[s.mainColumns, narrow && s.column]}><View style={[s.panel, { flex: 1 }]}><View style={s.panelPad}><Heading>Your fine breakdown</Heading><Text style={s.caption}>Recalculated from past check-ins. Today’s pending goals aren’t charged.</Text></View>{finesFor(challenge, userId, today).length ? finesFor(challenge, userId, today).map(f => <View key={f.id} style={s.ledgerRow}><View style={{ flex: 1 }}><Text style={s.goalTitle}>{f.title}</Text><Text style={s.caption}>{formatDate(f.period, true)} · {f.reason}</Text></View><Text style={s.moneyText}>{money(f.amount)}</Text></View>) : <View style={s.panelPad}><Text style={s.body}>No fines. Keep showing up for yourself.</Text></View>}<View style={s.panelPad}><Heading>Payment history</Heading><Text style={[s.caption, { marginBottom: 12 }]}>Self-reported records; payments are not verified.</Text>{challenge.payments.filter(p => p.userId === userId).map(p => <View key={p.id} style={s.paymentRow}><View style={{ flex: 1 }}><Text style={s.body}>{p.note}</Text><Text style={s.caption}>{formatDate(p.date, true)} · Manually recorded</Text></View><Text style={[s.moneyText, { color: C.green }]}>{money(p.amount)}</Text></View>)}{!challenge.payments.some(p => p.userId === userId) && <Text style={s.caption}>Your recorded payments will appear here.</Text>}</View></View><View style={[s.aside, narrow && { width: '100%' }]}><View style={s.groupPanel}><Heading>Record a payment</Heading><Text style={[s.caption, { marginBottom: 20 }]}>Already settled up outside the app? Add a record here. No money is transferred.</Text><Field label="Amount (₹)" value={payAmount} onChange={setPayAmount} numeric placeholder={String(balance.due)} /><Field label="Payment note (optional)" value={payNote} onChange={v => setPayNote(v.slice(0, 500))} placeholder="e.g. Sent to the group pot" /><Button icon="checkmark" disabled={busy || !balance.due} onPress={pay}>Record payment</Button></View><View style={s.groupPanel}><Heading>Group dues</Heading>{challenge.members.map((m, i) => <View key={m.id} style={s.friendRow}><Avatar name={m.name} small second={i % 2 === 1} /><Text style={[s.body, { flex: 1 }]}>{m.name}</Text><Text style={s.moneyText}>{money(balanceFor(challenge, m.id, today).due)}</Text></View>)}</View></View></View></>}
          {(page === 'Ledger' || page === 'Progress') && !challenge && <Empty title="Something to work toward." body="Create or join a challenge to start tracking progress and dues." action="Find your challenge" onPress={() => go('Challenges')} />}
          {page === 'Account' && <><View style={s.pageHeading}><View><Text style={s.h1}>Your space. Your pace.</Text><Text style={s.subtitle}>Manage your account and workspace.</Text></View></View><View style={[s.mainColumns, narrow && s.column]}><View style={[s.panel, { flex: 1 }]}><View style={s.panelPad}><Heading>{session ? 'Your Supabase account' : signup ? 'Start something together.' : 'Connect with your friends.'}</Heading>{session ? <><Text style={s.body}>{session.user.email}</Text><Text style={[s.caption, { marginVertical: 16 }]}>{demo ? 'You’re viewing local demo data.' : 'You’re using your shared Supabase workspace.'}</Text>{demo && <Button disabled={busy} onPress={() => act(async () => { if (dirty) throw new Error('Save or discard your demo check-in first.'); const items = await repo.loadChallenges(); setChallenges(items); setSelected(items[0]?.id ?? ''); setDemo(false); setPage('Challenges'); })}>Open shared workspace</Button>}<View style={{ marginTop: 12 }}><Button secondary disabled={busy} onPress={() => act(async () => { if (dirty) throw new Error('Save or discard your check-in before signing out.'); const result = await supabase!.auth.signOut(); if (result.error) throw result.error; setDemo(true); const saved = await AsyncStorage.getItem('befit-demo-v1'); setChallenges(saved ? JSON.parse(saved) : seed()); setSelected(''); setPage('Today'); setDirty(false); })}>Sign out</Button></View></> : <><Text style={[s.body, { marginBottom: 24 }]}>Your real challenges live in a private group. Sign in to create one or use a friend’s invite code.</Text>{!supabase && <View style={[s.lockNote, { marginBottom: 20, borderRadius: 8 }]}><Icon name="information-circle-outline" size={18} /><Text style={[s.caption, { flex: 1 }]}>Supabase isn’t connected yet. Add the environment values and run the included database migration to enable accounts.</Text></View>}{signup && <Field label="Your name" value={displayName} onChange={v => setDisplayName(v.slice(0, 80))} placeholder="What should friends call you?" />}<Field label="Email" value={email} onChange={setEmail} placeholder="you@example.com" /><Field label="Password" value={password} onChange={setPassword} placeholder="At least 8 characters" secure /><Button disabled={busy || !supabase} onPress={authenticate}>{busy ? 'Connecting…' : signup ? 'Create account' : 'Sign in'}</Button><Pressable accessibilityRole="button" onPress={() => setSignup(!signup)} style={[s.textAction, { marginTop: 20 }]}><Text style={s.link}>{signup ? 'Already have an account? Sign in' : 'New here? Create an account'}</Text></Pressable>{!signup && supabase && <Pressable accessibilityRole="button" onPress={() => act(async () => { if (!email.includes('@')) throw new Error('Enter your email above first.'); const { error } = await supabase!.auth.resetPasswordForEmail(email.trim()); if (error) throw error; setMessage('Password reset email sent. Follow the link to reset your password.'); })} style={s.textAction}><Text style={s.link}>Forgot your password?</Text></Pressable>}</>}</View></View><View style={[s.aside, narrow && { width: '100%' }]}><View style={s.groupPanel}><Heading>Local demo</Heading><Text style={s.caption}>Sample people and check-ins. Nothing from the private chat was imported.</Text>{demo && <><Text style={[s.label, { marginTop: 24, marginBottom: 12 }]}>Preview as</Text><View style={s.row}>{[{ id: 'demo-you', name: 'Helen' }, { id: 'demo-friend', name: 'Charith' }].map(m => <Button key={m.id} secondary={demoUser !== m.id} disabled={dirty} onPress={() => setDemoUser(m.id)}>{m.name}</Button>)}</View></>}<View style={{ marginTop: 20 }}><Button secondary disabled={busy || dirty} onPress={() => act(async () => { const items = seed(); await AsyncStorage.setItem('befit-demo-v1', JSON.stringify(items)); setDemo(true); setChallenges(items); setSelected(items[0]!.id); setDemoUser('demo-you'); setDate(todayIn()); setPage('Today'); setMessage('Local demo reset. Shared Supabase data was not changed.'); })}>Reset demo</Button></View></View><View style={s.weeklyNote}><Text style={s.noteTitle}>A few shared ground rules</Text><Text style={s.noteCopy}>Weeks run Sunday to Saturday. Daily check-ins close at midnight in your challenge’s timezone. Yesterday stays editable. Older entries lock.</Text><Text style={[s.noteCopy, { marginTop: 12 }]}>Weekly fines are flat, not per missed day. Partial weeks use a target capped to the days you were a member.</Text></View></View></View></>}
          </>}
          <View style={s.footer}><Text style={s.caption}>One check-in at a time. Better together.</Text><Text style={s.caption}>Be Fit · {challenge?.timezone ?? 'Asia/Kolkata'}</Text></View>
        </View>
      </ScrollView>
    </View>
    {mobile && <View style={s.bottomNav}>{nav}</View>}
  </View>;
}

function WeekPicker({ userId, challenge, date, today, dirty, onChange }: { userId: string; challenge: Challenge; date: string; today: string; dirty: boolean; onChange: (date: string) => void }) {
  const previous = addDays(weekStart(date), -1) >= challenge.start;
  const next = addDays(weekStart(date), 7) <= today && addDays(weekStart(date), 7) <= challenge.end;
  return <>
    <View style={[s.sectionHeading, { marginBottom: 8 }]}><Text style={s.h2}>Your daily check-in</Text><View style={[s.row, { gap: 0 }]}><Pressable accessibilityRole="button" accessibilityLabel="Previous week" accessibilityState={{ disabled: dirty || !previous }} disabled={dirty || !previous} onPress={() => onChange(addDays(date, -7) < challenge.start ? challenge.start : addDays(date, -7))} style={[s.iconButton, !previous && { opacity: .3 }]}><Icon name="chevron-back" size={18} /></Pressable><Pressable accessibilityRole="button" accessibilityLabel="Next week" accessibilityState={{ disabled: dirty || !next }} disabled={dirty || !next} onPress={() => onChange(addDays(date, 7) > today ? today : addDays(date, 7))} style={[s.iconButton, !next && { opacity: .3 }]}><Icon name="chevron-forward" size={18} /></Pressable></View></View>
    <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ flexGrow: 1, justifyContent: 'space-between', gap: 4 }} style={{ marginBottom: 16 }}>
      {dateRange(weekStart(date), addDays(weekStart(date), 6)).map(d => { const selectedDay = d === date; const inRange = d >= challenge.start && d <= challenge.end && d <= today; const checked = challenge.checkins.some(x => x.date === d && x.userId === userId); return <Pressable key={d} accessibilityRole="button" accessibilityLabel={`View ${d}`} accessibilityState={{ selected: selectedDay, disabled: !inRange || dirty }} disabled={!inRange || dirty} onPress={() => onChange(d)} style={[s.day, { flex: undefined, minWidth: 44, width: 44, minHeight: 64 }, selectedDay && s.daySelected, !inRange && { opacity: .3 }]}><Text style={[s.dayName, selectedDay && { color: C.pale }]}>{new Date(d + 'T12:00:00Z').toLocaleDateString('en', { weekday: 'narrow', timeZone: 'UTC' })}</Text><Text style={[s.dayNumber, selectedDay && { color: C.white }]}>{Number(d.slice(-2))}</Text><View style={[s.dayDot, { backgroundColor: checked ? selectedDay ? C.white : C.green : 'transparent' }]} /></Pressable>; })}
    </ScrollView>
  </>;
}
function Empty({ title, body, action, onPress }: { title: string; body: string; action: string; onPress: () => void }) { return <View style={s.empty}><View style={s.emptyIcon}><Icon name="leaf-outline" color={C.green} size={36} /></View><Text style={s.h1}>{title}</Text><Text style={[s.subtitle, { textAlign: 'center', marginBottom: 24 }]}>{body}</Text><Button icon="add" onPress={onPress}>{action}</Button></View>; }

function CreateForm({ mobile, busy, onCancel, onSubmit }: { mobile: boolean; busy: boolean; onCancel: () => void; onSubmit: (input: { name: string; description: string; start: string; end: string; timezone: string; goals: Goal[] }) => Promise<void> }) {
  const [name, setName] = useState(''); const [description, setDescription] = useState(''); const [start, setStart] = useState(todayIn()); const [end, setEnd] = useState(addDays(todayIn(), 29)); const [timezone, setTimezone] = useState('Asia/Kolkata');
  const [goals, setGoals] = useState<Goal[]>(starterGoals.map(g => ({ ...g }))); const [error, setError] = useState('');
  function edit(id: string, patch: Partial<Goal>) { setGoals(items => items.map(g => g.id === id ? { ...g, ...patch } : g)); }
  async function submit() { setError(''); try {
    if (!name.trim()) throw new Error('Give your challenge a name.');
    try { todayIn(timezone); } catch { throw new Error('Use an IANA timezone, such as Asia/Kolkata or Europe/London.'); }
    const validDate = (v: string) => /^\d{4}-\d{2}-\d{2}$/.test(v) && !isNaN(Date.parse(v + 'T12:00:00Z')) && new Date(v + 'T12:00:00Z').toISOString().slice(0, 10) === v;
    if (!validDate(start) || !validDate(end) || start < todayIn(timezone) || end < start || end > addDays(start, 365)) throw new Error('Use valid YYYY-MM-DD dates, starting today or later, with an end within one year.');
    if (!goals.length) throw new Error('Add at least one goal.');
    for (const g of goals) { const issue = validateGoal(g); if (issue) throw new Error(issue); }
    await onSubmit({ name: name.trim(), description: description.trim(), start, end, timezone, goals });
  } catch (e) { setError((e as Error).message); } }
  return <><View style={s.pageHeading}><View><Text style={s.h1}>Make a pact.</Text><Text style={s.subtitle}>Choose goals you can agree on. Leave room to be human.</Text></View></View><View style={[s.panel, { maxWidth: 850 }]}><View style={s.panelPad}><Heading>Your challenge</Heading><Field label="Challenge name" value={name} onChange={v => setName(v.slice(0, 80))} placeholder="e.g. The November pact" /><Field label="What’s the plan? (optional)" value={description} onChange={v => setDescription(v.slice(0, 500))} placeholder="A shared reason to keep showing up." /><View style={[s.row, mobile && s.column, { alignItems: 'stretch' }]}><View style={{ flex: 1 }}><Field label="Start date (YYYY-MM-DD)" value={start} onChange={setStart} /></View><View style={{ flex: 1 }}><Field label="End date (YYYY-MM-DD)" value={end} onChange={setEnd} /></View></View><Field label="Challenge timezone" value={timezone} onChange={setTimezone} /><Text style={s.caption}>Daily deadlines use this timezone. Weeks run Sunday to Saturday.</Text></View><View style={s.panelPad}><Heading aside={<Text style={s.caption}>{goals.length} / 20</Text>}>Set your goals</Heading><Text style={[s.body, { marginBottom: 20 }]}>Start with these or make them your own. Set the penalty to 0 for a goal without fines. Later rule changes apply going forward and preserve past fines.</Text>{goals.map((g, index) => <View key={g.id} style={s.goalEditor}><View style={s.row}><Text style={[s.label, { flex: 1 }]}>Goal {index + 1}</Text><Pressable accessibilityRole="button" accessibilityLabel={`Remove goal ${index + 1}`} onPress={() => setGoals(items => items.filter(item => item.id !== g.id))} style={s.iconButton}><Icon name="trash-outline" size={18} color={C.orange} /></Pressable></View><Field label={`Goal ${index + 1} name`} value={g.title} onChange={v => edit(g.id, { title: v.slice(0, 100) })} /><Field label={`Goal ${index + 1} rule or exemptions`} value={g.description} onChange={v => edit(g.id, { description: v.slice(0, 500) })} /><View style={[s.row, { marginBottom: 16 }]}>{(['daily', 'weekly'] as const).map(f => <Button key={f} secondary={g.frequency !== f} onPress={() => edit(g.id, { frequency: f, target: f === 'daily' ? 1 : 5 })}>{f === 'daily' ? 'Daily' : 'Weekly'}</Button>)}</View><View style={[s.row, mobile && s.column, { alignItems: 'stretch' }]}><View style={{ flex: 1 }}><Field label={`Goal ${index + 1} penalty (₹)`} value={String(g.penalty)} onChange={v => edit(g.id, { penalty: v === '' ? 0 : Number(v) })} numeric /></View>{g.frequency === 'weekly' && <View style={{ flex: 1 }}><Field label={`Goal ${index + 1} days per week`} value={String(g.target)} onChange={v => edit(g.id, { target: v === '' ? 0 : Number(v) })} numeric /></View>}</View><Text style={s.caption}>{g.frequency === 'weekly' ? 'One flat fine if the weekly target is missed. Rest days are fine.' : 'One fine per missed daily goal after midnight.'}</Text></View>)}<Button secondary icon="add" disabled={goals.length >= 20} onPress={() => setGoals(items => [...items, { id: uid(), title: '', description: '', frequency: 'daily', target: 1, penalty: 0, icon: 'fitness-outline' }])}>Add a goal</Button>{!!error && <Text accessibilityRole="alert" style={[s.body, { color: C.orange, marginVertical: 16 }]}>{error}</Text>}<View style={[s.row, { marginTop: 32 }]}><Button icon="flag-outline" disabled={busy} onPress={submit}>{busy ? 'Creating…' : 'Create challenge'}</Button><Button secondary disabled={busy} onPress={onCancel}>Cancel</Button></View></View></View></>;
}

